// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        address initialOwner = c.owner();
        vm.assume(caller != initialOwner);
        vm.prank(caller);
        // Attempt to call owned() as a non-owner; the call should revert in reference
        (bool success, ) = address(c).call(abi.encodeWithSignature("owned()"));
        assertTrue(!success, "non-owner should not be able to call owned()");
        // After revert, owner must be unchanged
        address finalOwner = c.owner();
        assertTrue(finalOwner == initialOwner, "owner must remain unchanged after failed call");
    }
}

